def is3(vertices, edge_list=None):
    V=sorted(vertices); idx={v:i for i,v in enumerate(V)}
    n=len(V)
    adj=[set() for _ in range(n)]
    if edge_list is None:
        E=edges
    else: E=edge_list
    for u,v in E:
        if u in idx and v in idx:
            a=idx[u]; b=idx[v]; adj[a].add(b); adj[b].add(a)
    colors=[-1]*n
    # components? just dsatur
    def rec(count=0):
        if count==n: return True
        best=-1; key=(-1,-1)
        for i in range(n):
            if colors[i]<0:
                sat=len({colors[j] for j in adj[i] if colors[j]>=0})
                deg=len(adj[i])
                if (sat,deg)>key:
                    key=(sat,deg); best=i
        forb={colors[j] for j in adj[best] if colors[j]>=0}
        for c in range(3):
            if c not in forb:
                colors[best]=c
                if rec(count+1): return True
                colors[best]=-1
        return False
    return rec()

